            Describe.Lean(DescribeId.Create("seed-output"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/HistoryRecursion.seedOutput"), H("seedOutput"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Exact public source declaration and proof body; complete ambient scopes and imports are in the literal module above:\ndef seedOutput (f : K4.SeedLabel ↪ V) (A B : Finset V)\n    (hA : A ⊆ (seedGraph f).ground) :\n    Output (residual (seedGraph f).ground A B)\n      (corner (seedGraph f).ground A B (seedGraph f).rows.root) := by\n  have out := HistorySeed.seedCornerOutput f A B hA\n  have hr : (seedGraph f).rows.root = renameFamily f K4.seedGraphData.rows.root :=\n    PhysicalLabels.root K4.seedGraphData f s(0,0)\n  rw [hr]\n  exact out")))),
            Describe.Lean(DescribeId.Create("all-corners-output"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/HistoryRecursion.allCornersOutput"), H("allCornersOutput"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED. Exact public source declaration and proof body; complete ambient scopes and imports are in the literal module above:\ndef allCornersOutput {n : Nat} {G : Type} {g : GraphData G V}\n    (h : MixedHistory n G g) :\n    ∀ (A B : Finset V), A ⊆ g.ground → B ⊆ g.ground → Disjoint A B →\n      Output (residual g.ground A B) (corner g.ground A B g.rows.root) := by\n  induction h with\n  | seed f =>\n      intro A B hA hB hAB\n      exact seedOutput f A B hA\n  | attach old i ih =>\n      intro A B hA hB hAB\n      exact stepOutput old i A B hA hB hAB ih"))))
